import 'cart_item.dart';
class OrderModel { final String id,userId,status,paymentMethod; final List<CartItem> items; final double total; final DateTime? createdAt,estimatedDelivery; const OrderModel({required this.id,required this.userId,required this.status,required this.paymentMethod,required this.items,required this.total,this.createdAt,this.estimatedDelivery}); factory OrderModel.fromMap(String id,Map<String,dynamic> m)=>OrderModel(id:id,userId:m['userId']??'',status:m['status']??'placed',paymentMethod:m['paymentMethod']??'cod',items:List<Map<String,dynamic>>.from(m['items']??const []).map(CartItem.fromMap).toList(),total:(m['grandTotal']??0).toDouble(),createdAt:m['createdAt']?.toDate(),estimatedDelivery:m['estimatedDelivery']?.toDate()); }
